-- PostgreSQL implementation of the 18 documented business records.

CREATE TABLE user_account (
 user_id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE RESTRICT, role TEXT NOT NULL CHECK(role IN ('Administrator','Owner','Customer')),
 full_name TEXT NOT NULL, login_name TEXT NOT NULL UNIQUE,
 status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Inactive')), created_at TIMESTAMPTZ NOT NULL
);
CREATE TABLE sme (
 sme_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id UUID NOT NULL REFERENCES user_account(user_id),
 store_name TEXT NOT NULL, business_type TEXT NOT NULL, address TEXT NOT NULL,
 status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Active','Inactive')), registered_at TIMESTAMPTZ NOT NULL
);
CREATE TABLE category (
 category_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_name TEXT NOT NULL  UNIQUE,
 product_type TEXT NOT NULL CHECK(product_type IN ('Packaged Product','Clothing','Gadget','General Retail')),
 status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Archived'))
);
CREATE TABLE brand (
 brand_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, brand_name TEXT NOT NULL, search_key TEXT NOT NULL UNIQUE,
 status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Archived'))
);
CREATE TABLE product (
 product_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_id INTEGER NOT NULL REFERENCES category(category_id),
 brand_id INTEGER REFERENCES brand(brand_id), product_name TEXT NOT NULL, model_or_style TEXT,
 status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Archived'))
);
CREATE TABLE product_variation (
 variation_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES product(product_id),
 variation_name TEXT NOT NULL, size TEXT, color TEXT, flavor TEXT, capacity TEXT,
 net_quantity NUMERIC CHECK(net_quantity IS NULL OR net_quantity>0), net_unit TEXT CHECK(net_unit IN ('g','mL')),
 condition TEXT NOT NULL DEFAULT 'New' CHECK(condition IN ('New','Used')), stock_unit TEXT NOT NULL,
 other_details TEXT, variation_key TEXT NOT NULL, allow_price_reference BOOLEAN NOT NULL DEFAULT false,
 status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Archived')),
 UNIQUE(product_id,variation_key), CHECK((net_quantity IS NULL)=(net_unit IS NULL))
);
CREATE TABLE product_unit (
 unit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, variation_id INTEGER NOT NULL REFERENCES product_variation(variation_id),
 unit_name TEXT NOT NULL , stock_units INTEGER NOT NULL CHECK(stock_units>0), gtin TEXT UNIQUE,
 status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Archived')), UNIQUE(variation_id,unit_name,stock_units)
);
CREATE TABLE product_request (
 product_request_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sme_id INTEGER NOT NULL REFERENCES sme(sme_id), submitted_by UUID NOT NULL REFERENCES user_account(user_id),
 requested_details TEXT NOT NULL, submitted_at TIMESTAMPTZ NOT NULL,
 status TEXT NOT NULL DEFAULT 'Pending Product Review' CHECK(status IN ('Pending Product Review','Approved','Rejected')),
 reviewed_by UUID REFERENCES user_account(user_id), reviewed_at TIMESTAMPTZ, decision_reason TEXT,
 approved_variation_id INTEGER REFERENCES product_variation(variation_id), approved_unit_id INTEGER REFERENCES product_unit(unit_id)
);
CREATE TABLE store_product (
 store_product_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sme_id INTEGER NOT NULL REFERENCES sme(sme_id), variation_id INTEGER NOT NULL REFERENCES product_variation(variation_id),
 stock_quantity INTEGER NOT NULL DEFAULT 0 CHECK(stock_quantity>=0), low_stock_level INTEGER NOT NULL DEFAULT 0 CHECK(low_stock_level>=0),
 latest_unit_cost NUMERIC CHECK(latest_unit_cost IS NULL OR latest_unit_cost>=0), status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Archived')),
 UNIQUE(sme_id,variation_id)
);
CREATE TABLE store_price (
 store_price_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, store_product_id INTEGER NOT NULL REFERENCES store_product(store_product_id), unit_id INTEGER NOT NULL REFERENCES product_unit(unit_id),
 regular_price NUMERIC CHECK(regular_price IS NULL OR regular_price>0), price_updated_at TIMESTAMPTZ,
 status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Archived')), UNIQUE(store_product_id,unit_id)
);
CREATE TABLE price_rule (
 rule_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, allowance_percent NUMERIC NOT NULL CHECK(allowance_percent>=0), minimum_stores INTEGER NOT NULL CHECK(minimum_stores>0),
 maximum_age_days INTEGER NOT NULL CHECK(maximum_age_days>0), effective_from TIMESTAMPTZ NOT NULL, created_by UUID NOT NULL REFERENCES user_account(user_id),
 status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Inactive'))
);
CREATE UNIQUE INDEX one_active_rule ON price_rule(status) WHERE status='Active';
CREATE TABLE price_request (
 price_request_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, store_price_id INTEGER NOT NULL REFERENCES store_price(store_price_id), submitted_by UUID NOT NULL REFERENCES user_account(user_id),
 previous_price NUMERIC, proposed_price NUMERIC NOT NULL CHECK(proposed_price>0), owner_reason TEXT,
 submitted_at TIMESTAMPTZ NOT NULL, checked_at TIMESTAMPTZ, rule_id INTEGER REFERENCES price_rule(rule_id), reference_median NUMERIC,
 reference_count INTEGER NOT NULL DEFAULT 0 CHECK(reference_count>=0), allowed_price NUMERIC, review_reason TEXT,
 status TEXT NOT NULL DEFAULT 'Pending Price Review' CHECK(status IN ('Pending Price Review','Approved','Rejected','Withdrawn')),
 decision_source TEXT CHECK(decision_source IN ('System','Administrator')), reviewed_by UUID REFERENCES user_account(user_id), decided_at TIMESTAMPTZ, decision_reason TEXT,
 previous_request_id INTEGER REFERENCES price_request(price_request_id)
);
CREATE UNIQUE INDEX one_pending_price ON price_request(store_price_id) WHERE status='Pending Price Review';
CREATE TABLE price_reference (
 price_request_id INTEGER NOT NULL REFERENCES price_request(price_request_id), reference_sme_id INTEGER NOT NULL REFERENCES sme(sme_id),
 price_history_id INTEGER NOT NULL, PRIMARY KEY(price_request_id,reference_sme_id)
);
CREATE TABLE price_history (
 price_history_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, store_price_id INTEGER NOT NULL REFERENCES store_price(store_price_id),
 price_request_id INTEGER NOT NULL UNIQUE REFERENCES price_request(price_request_id), old_price NUMERIC, new_price NUMERIC NOT NULL CHECK(new_price>0), effective_at TIMESTAMPTZ NOT NULL
);
CREATE TABLE stock_transaction (
 stock_transaction_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, store_product_id INTEGER NOT NULL REFERENCES store_product(store_product_id), recorded_by UUID NOT NULL REFERENCES user_account(user_id),
 transaction_type TEXT NOT NULL CHECK(transaction_type IN ('Opening','Restock','Sale','Loss','Spoilage','Damage','Correction','Reversal')),
 quantity_change INTEGER NOT NULL, unit_id INTEGER REFERENCES product_unit(unit_id), entered_quantity INTEGER CHECK(entered_quantity IS NULL OR entered_quantity>0),
 units_per_package INTEGER CHECK(units_per_package IS NULL OR units_per_package>0), total_purchase_cost NUMERIC, total_sale_amount NUMERIC,
 unit_purchase_cost NUMERIC CHECK(unit_purchase_cost IS NULL OR unit_purchase_cost>=0), price_history_id INTEGER REFERENCES price_history(price_history_id),
 promotion_entry_id INTEGER, correction_of_id INTEGER REFERENCES stock_transaction(stock_transaction_id),
 reason TEXT, recorded_at TIMESTAMPTZ NOT NULL
);
CREATE UNIQUE INDEX one_opening ON stock_transaction(store_product_id) WHERE transaction_type='Opening';
CREATE UNIQUE INDEX one_reversal ON stock_transaction(correction_of_id) WHERE transaction_type='Reversal';
CREATE TABLE promotion (
 promotion_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, promotion_name TEXT NOT NULL, description TEXT, starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL CHECK(ends_at>starts_at),
 created_by UUID NOT NULL REFERENCES user_account(user_id), status TEXT NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Cancelled'))
);
CREATE TABLE promotion_entry (
 promotion_entry_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, promotion_id INTEGER NOT NULL REFERENCES promotion(promotion_id), store_price_id INTEGER NOT NULL REFERENCES store_price(store_price_id),
 submitted_by UUID NOT NULL REFERENCES user_account(user_id), submitted_at TIMESTAMPTZ NOT NULL, promotion_price NUMERIC NOT NULL CHECK(promotion_price>0),
 regular_history_id INTEGER NOT NULL REFERENCES price_history(price_history_id), status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Approved','Rejected','Withdrawn')),
 reviewed_by UUID REFERENCES user_account(user_id), decided_at TIMESTAMPTZ, decision_reason TEXT, previous_entry_id INTEGER REFERENCES promotion_entry(promotion_entry_id)
);
CREATE UNIQUE INDEX one_live_promo_submission ON promotion_entry(promotion_id,store_price_id) WHERE status IN ('Pending','Approved');
CREATE TABLE customer_report (
 customer_report_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id UUID NOT NULL REFERENCES user_account(user_id), store_price_id INTEGER NOT NULL REFERENCES store_price(store_price_id),
 listed_price NUMERIC NOT NULL CHECK(listed_price>0), charged_price NUMERIC CHECK(charged_price IS NULL OR charged_price>0), transaction_at TIMESTAMPTZ, description TEXT NOT NULL,
 evidence_reference TEXT, submitted_at TIMESTAMPTZ NOT NULL, owner_response TEXT, responded_by UUID REFERENCES user_account(user_id), responded_at TIMESTAMPTZ,
 status TEXT NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Under Review','Closed')), reviewed_by UUID REFERENCES user_account(user_id),
 outcome TEXT CHECK(outcome IN ('Confirmed Discrepancy','Package Mismatch','Insufficient Evidence','No Discrepancy Established')), outcome_details TEXT, closed_at TIMESTAMPTZ
);

CREATE INDEX store_owner ON sme(owner_id);
CREATE INDEX variation_product ON product_variation(product_id);
CREATE INDEX stock_store ON store_product(sme_id);
CREATE INDEX price_product ON store_price(store_product_id);
CREATE INDEX history_option ON price_history(store_price_id,price_history_id);
CREATE INDEX stock_product_date ON stock_transaction(store_product_id,recorded_at);
CREATE INDEX request_status ON price_request(status,submitted_at);
CREATE INDEX concern_status ON customer_report(status,customer_id);
CREATE INDEX promo_option ON promotion_entry(store_price_id,status);

ALTER TABLE price_reference ADD FOREIGN KEY(price_history_id) REFERENCES price_history(price_history_id);
ALTER TABLE stock_transaction ADD FOREIGN KEY(promotion_entry_id) REFERENCES promotion_entry(promotion_entry_id);

CREATE UNIQUE INDEX category_name_key ON category(lower(trim(category_name)));
CREATE UNIQUE INDEX unit_gtin ON product_unit(gtin) WHERE gtin IS NOT NULL;

CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM public, anon, authenticated;
GRANT USAGE ON SCHEMA private TO authenticated, anon;

CREATE FUNCTION private.current_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
 SELECT role FROM public.user_account WHERE user_id=auth.uid() AND status='Active'
$$;
CREATE FUNCTION private.can_store(id bigint) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
 SELECT coalesce(private.current_role()='Administrator' OR (private.current_role()='Owner' AND EXISTS(SELECT 1 FROM public.sme WHERE sme_id=id AND owner_id=auth.uid())),false)
$$;
CREATE FUNCTION private.can_product(id bigint) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
 SELECT EXISTS(SELECT 1 FROM public.store_product WHERE store_product_id=id AND private.can_store(sme_id))
$$;
CREATE FUNCTION private.can_price(id bigint) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
 SELECT EXISTS(SELECT 1 FROM public.store_price WHERE store_price_id=id AND private.can_product(store_product_id))
$$;
CREATE FUNCTION private.new_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
 INSERT INTO public.user_account(user_id,role,full_name,login_name,status,created_at)
 VALUES(new.id,'Customer',left(coalesce(nullif(new.raw_user_meta_data->>'full_name',''),'New account'),120),new.email,'Active',now());
 RETURN new;
END $$;
CREATE TRIGGER create_mis_account AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION private.new_account();
INSERT INTO public.user_account(user_id,role,full_name,login_name,status,created_at)
 SELECT id,'Customer',coalesce(nullif(raw_user_meta_data->>'full_name',''),'New account'),email,'Active',created_at FROM auth.users;

-- No client can insert/update/delete business tables. Commands below validate each transition.
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['user_account','sme','category','brand','product','product_variation','product_unit','product_request','store_product','store_price','price_rule','price_request','price_reference','price_history','stock_transaction','promotion','promotion_entry','customer_report'] LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('REVOKE ALL ON public.%I FROM anon,authenticated',t);
 EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t);
 END LOOP;
END $$;
CREATE POLICY account_read ON user_account FOR SELECT TO authenticated USING(user_id=(select auth.uid()) OR (select private.current_role())='Administrator');
CREATE POLICY store_read ON sme FOR SELECT TO authenticated USING(private.can_store(sme_id));
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['category','brand','product','product_variation','product_unit','price_rule','promotion'] LOOP
 EXECUTE format('CREATE POLICY catalog_read ON public.%I FOR SELECT TO authenticated USING ((select private.current_role()) IS NOT NULL)',t);
 END LOOP;
END $$;
CREATE POLICY product_request_read ON product_request FOR SELECT TO authenticated USING(private.can_store(sme_id));
CREATE POLICY store_product_read ON store_product FOR SELECT TO authenticated USING(private.can_store(sme_id));
CREATE POLICY store_price_read ON store_price FOR SELECT TO authenticated USING(private.can_product(store_product_id));
CREATE POLICY price_request_read ON price_request FOR SELECT TO authenticated USING(private.can_price(store_price_id));
CREATE POLICY reference_read ON price_reference FOR SELECT TO authenticated USING((select private.current_role())='Administrator');
CREATE POLICY history_read ON price_history FOR SELECT TO authenticated USING(private.can_price(store_price_id));
CREATE POLICY transaction_read ON stock_transaction FOR SELECT TO authenticated USING(private.can_product(store_product_id));
CREATE POLICY entry_read ON promotion_entry FOR SELECT TO authenticated USING(private.can_price(store_price_id));
CREATE POLICY report_read ON customer_report FOR SELECT TO authenticated USING((customer_id=(select auth.uid()) AND (select private.current_role())='Customer') OR private.can_price(store_price_id));

CREATE FUNCTION private.active_option(id bigint) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
 SELECT EXISTS(SELECT 1 FROM public.store_price s
 JOIN public.store_product sp USING(store_product_id) JOIN public.sme sm USING(sme_id)
 JOIN public.user_account a ON a.user_id=sm.owner_id JOIN public.product_variation v USING(variation_id)
 JOIN public.product p USING(product_id) JOIN public.category c USING(category_id)
 LEFT JOIN public.brand b USING(brand_id) JOIN public.product_unit u ON u.unit_id=s.unit_id AND u.variation_id=v.variation_id
 WHERE s.store_price_id=id AND s.status='Active' AND sp.status='Active' AND sm.status='Active' AND a.status='Active'
 AND v.status='Active' AND p.status='Active' AND c.status='Active' AND (b.brand_id IS NULL OR b.status='Active') AND u.status='Active')
$$;
CREATE FUNCTION private.public_listings(search text DEFAULT '') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
 SELECT coalesce(jsonb_agg(x ORDER BY x.product_name,x.store_name,x.store_price_id),'[]'::jsonb) FROM (
 SELECT s.store_price_id,sm.store_name,sm.business_type,sm.address,p.product_name,p.model_or_style,c.category_name,c.product_type,b.brand_name,
 v.variation_name,v.size,v.color,v.flavor,v.capacity,v.net_quantity,v.net_unit,v.condition,v.stock_unit,v.other_details,
 u.unit_name,u.stock_units,s.regular_price,coalesce(pe.promotion_price,s.regular_price) selling_price,pe.promotion_name,
 CASE WHEN sp.stock_quantity>=u.stock_units THEN 'Available' ELSE 'Out of stock' END availability,s.price_updated_at,
 (SELECT max(recorded_at) FROM public.stock_transaction t WHERE t.store_product_id=sp.store_product_id) availability_updated_at
 FROM public.store_price s JOIN public.store_product sp USING(store_product_id) JOIN public.sme sm USING(sme_id)
 JOIN public.product_variation v USING(variation_id) JOIN public.product p USING(product_id)
 JOIN public.category c USING(category_id) LEFT JOIN public.brand b USING(brand_id) JOIN public.product_unit u ON u.unit_id=s.unit_id
 LEFT JOIN LATERAL (
 SELECT e.promotion_price,pr.promotion_name FROM public.promotion_entry e JOIN public.promotion pr USING(promotion_id)
 WHERE e.store_price_id=s.store_price_id AND e.status='Approved' AND pr.status='Open' AND now()>=pr.starts_at AND now()<pr.ends_at
 AND e.promotion_price<s.regular_price ORDER BY e.promotion_entry_id DESC LIMIT 1) pe ON true
 WHERE s.regular_price IS NOT NULL AND private.active_option(s.store_price_id)
 AND concat_ws(' ',p.product_name,p.model_or_style,b.brand_name,v.variation_name,v.size,v.color,v.flavor,v.capacity,u.unit_name,sm.store_name,c.category_name) ILIKE '%'||left(search,120)||'%'
 ) x
$$;
CREATE FUNCTION public.browse_products(search text DEFAULT '') RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $$ SELECT private.public_listings(search) $$;
REVOKE ALL ON FUNCTION public.browse_products(text) FROM public;
GRANT EXECUTE ON FUNCTION public.browse_products(text) TO anon,authenticated;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA private FROM public,anon,authenticated;
GRANT EXECUTE ON FUNCTION private.current_role(),private.can_store(bigint),private.can_product(bigint),private.can_price(bigint) TO authenticated;
GRANT EXECUTE ON FUNCTION private.public_listings(text) TO anon,authenticated;

CREATE FUNCTION private.require_role(allowed text[]) RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(private.current_role()=ANY(allowed),false) THEN RAISE EXCEPTION 'You do not have access to this action.'; END IF;
 RETURN auth.uid();
END $$;
CREATE FUNCTION private.required(value text,label text) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path = '' AS $$
BEGIN IF trim(coalesce(value,''))='' OR length(value)>4000 THEN RAISE EXCEPTION 'Enter a valid % (up to 4000 characters).',label; END IF; RETURN trim(value); END $$;
CREATE FUNCTION private.money(value text,allow_zero boolean DEFAULT false) RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path = '' AS $$
DECLARE n numeric; BEGIN
 n:=value::numeric;
 IF n IS NULL OR n::text IN ('NaN','Infinity','-Infinity') OR n<0 OR (n=0 AND NOT allow_zero) OR n>1000000000 OR n<>round(n,2) THEN RAISE EXCEPTION 'Enter an amount with at most two decimal places.'; END IF;
 RETURN n;
END $$;
CREATE FUNCTION private.own_store(id bigint) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
 PERFORM private.require_role(ARRAY['Owner']);
 IF NOT EXISTS(SELECT 1 FROM public.sme WHERE sme_id=id AND owner_id=auth.uid() AND status='Active') THEN RAISE EXCEPTION 'Choose your active store.'; END IF;
END $$;
CREATE FUNCTION private.own_product(id bigint) RETURNS public.store_product LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE sp public.store_product; BEGIN
 SELECT * INTO STRICT sp FROM public.store_product WHERE store_product_id=id FOR UPDATE;
 PERFORM private.own_store(sp.sme_id);
 IF sp.status<>'Active' OR NOT EXISTS(SELECT 1 FROM public.product_variation v JOIN public.product p USING(product_id) JOIN public.category c USING(category_id) LEFT JOIN public.brand b USING(brand_id) WHERE v.variation_id=sp.variation_id AND v.status='Active' AND p.status='Active' AND c.status='Active' AND (b.brand_id IS NULL OR b.status='Active')) THEN RAISE EXCEPTION 'This product is not active.'; END IF;
 RETURN sp;
END $$;
CREATE FUNCTION private.own_option(id bigint) RETURNS public.store_price LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE opt public.store_price; sp public.store_product; BEGIN
 SELECT * INTO STRICT opt FROM public.store_price WHERE store_price_id=id FOR UPDATE;
 sp:=private.own_product(opt.store_product_id);
 IF NOT private.active_option(id) THEN RAISE EXCEPTION 'Choose an active product and selling unit.'; END IF;
 RETURN opt;
END $$;
CREATE FUNCTION private.activate_price(id bigint,source text,reviewer uuid,reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE r public.price_request; p public.store_price; BEGIN
 SELECT * INTO STRICT r FROM public.price_request WHERE price_request_id=id FOR UPDATE;
 SELECT * INTO STRICT p FROM public.store_price WHERE store_price_id=r.store_price_id FOR UPDATE;
 IF r.status<>'Pending Price Review' OR NOT private.active_option(p.store_price_id) THEN RAISE EXCEPTION 'This request or listing is no longer active.'; END IF;
 IF p.regular_price IS DISTINCT FROM r.previous_price THEN RAISE EXCEPTION 'The current price changed. Submit a new request.'; END IF;
 UPDATE public.price_request SET status='Approved',decision_source=source,reviewed_by=reviewer,decided_at=now(),decision_reason=reason WHERE price_request_id=id;
 UPDATE public.store_price SET regular_price=r.proposed_price,price_updated_at=now() WHERE store_price_id=p.store_price_id;
 INSERT INTO public.price_history(store_price_id,price_request_id,old_price,new_price,effective_at) VALUES(p.store_price_id,id,p.regular_price,r.proposed_price,now());
END $$;

CREATE FUNCTION private.submit_price(a jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE uid uuid; opt public.store_price; sp public.store_product; rule public.price_rule; id bigint; proposal numeric; prior bigint; count_sources integer; median numeric; cutoff numeric; reason text; reliable boolean;
BEGIN
 uid:=private.require_role(ARRAY['Owner']); PERFORM pg_advisory_xact_lock(731901);
 opt:=private.own_option((a->>'store_price_id')::bigint);
 SELECT * INTO sp FROM public.store_product WHERE store_product_id=opt.store_product_id;
 proposal:=private.money(a->>'proposed_price');
 IF proposal IS NOT DISTINCT FROM opt.regular_price THEN RAISE EXCEPTION 'This is already the approved price.'; END IF;
 prior:=nullif(a->>'previous_request_id','')::bigint;
 IF prior IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.price_request WHERE price_request_id=prior AND store_price_id=opt.store_price_id AND status IN ('Rejected','Withdrawn')) THEN RAISE EXCEPTION 'Choose a rejected or withdrawn request for this same listing.'; END IF;
 SELECT * INTO rule FROM public.price_rule WHERE status='Active' AND effective_from<=now();
 SELECT allow_price_reference INTO reliable FROM public.product_variation WHERE variation_id=sp.variation_id;
 INSERT INTO public.price_request(store_price_id,submitted_by,previous_price,proposed_price,owner_reason,submitted_at,checked_at,rule_id,previous_request_id)
 VALUES(opt.store_price_id,uid,opt.regular_price,proposal,nullif(trim(a->>'owner_reason'),''),now(),now(),rule.rule_id,prior) RETURNING price_request_id INTO id;
 IF rule.rule_id IS NOT NULL AND reliable THEN
 INSERT INTO public.price_reference(price_request_id,reference_sme_id,price_history_id)
 SELECT id,osp.sme_id,h.price_history_id FROM public.store_price op
 JOIN public.store_product osp ON osp.store_product_id=op.store_product_id
 JOIN LATERAL (SELECT ph.* FROM public.price_history ph WHERE ph.store_price_id=op.store_price_id ORDER BY ph.price_history_id DESC LIMIT 1) h ON true
 WHERE osp.variation_id=sp.variation_id AND op.unit_id=opt.unit_id AND osp.sme_id<>sp.sme_id
 AND private.active_option(op.store_price_id) AND op.regular_price=h.new_price AND op.price_updated_at=h.effective_at
 AND h.effective_at>=now()-make_interval(days=>rule.maximum_age_days);
 END IF;
 SELECT count(*),percentile_cont(0.5) WITHIN GROUP(ORDER BY h.new_price) INTO count_sources,median
 FROM public.price_reference r JOIN public.price_history h USING(price_history_id) WHERE r.price_request_id=id;
 cutoff:=floor(median*(1+rule.allowance_percent/100)*100)/100;
 reason:=CASE WHEN NOT reliable THEN 'Unreliable Product Match' WHEN rule.rule_id IS NULL THEN 'No Active Rule' WHEN count_sources<rule.minimum_stores THEN 'Too Few References' WHEN proposal>cutoff THEN 'Above Reference' ELSE NULL END;
 UPDATE public.price_request SET reference_count=count_sources,reference_median=median,allowed_price=cutoff,review_reason=reason WHERE price_request_id=id;
 IF reason IS NULL THEN PERFORM private.activate_price(id,'System',NULL,'Within the current price rule.'); END IF;
 RETURN jsonb_build_object('id',id,'message',CASE WHEN reason IS NULL THEN 'Price approved.' ELSE 'Pending Price Review: '||reason||'. Your current approved price stays in use.' END);
END $$;
CREATE FUNCTION private.review_price(a jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE uid uuid; r public.price_request; reason text; decision text; BEGIN
 uid:=private.require_role(ARRAY['Administrator']); PERFORM pg_advisory_xact_lock(731901);
 SELECT * INTO STRICT r FROM public.price_request WHERE price_request_id=(a->>'price_request_id')::bigint FOR UPDATE;
 IF r.status<>'Pending Price Review' THEN RAISE EXCEPTION 'This request is already decided.'; END IF;
 reason:=private.required(a->>'decision_reason','decision reason'); decision:=a->>'decision';
 IF decision='Approved' THEN
 IF r.review_reason='Above Reference' AND trim(coalesce(r.owner_reason,''))='' THEN RAISE EXCEPTION 'Ask the Owner to explain the higher price before approval.'; END IF;
 PERFORM private.activate_price(r.price_request_id,'Administrator',uid,reason);
 ELSIF decision='Rejected' THEN UPDATE public.price_request SET status='Rejected',decision_source='Administrator',reviewed_by=uid,decided_at=now(),decision_reason=reason WHERE price_request_id=r.price_request_id;
 ELSE RAISE EXCEPTION 'Choose Approved or Rejected.'; END IF;
 RETURN jsonb_build_object('message','Price request '||lower(decision)||'.');
END $$;

CREATE FUNCTION private.record_stock(a jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE uid uuid; sp public.store_product; u public.product_unit; opt public.store_price; old public.stock_transaction; t public.stock_transaction; q integer; expected numeric; cost numeric; effective numeric; history bigint; promo bigint;
BEGIN
 uid:=private.require_role(ARRAY['Owner']); sp:=private.own_product((a->>'store_product_id')::bigint);
 t.store_product_id:=sp.store_product_id; t.recorded_by:=uid; t.recorded_at:=now(); t.transaction_type:=a->>'transaction_type'; t.reason:=nullif(trim(a->>'reason'),'');
 IF t.transaction_type IN ('Loss','Spoilage','Damage','Correction','Reversal') THEN t.reason:=private.required(t.reason,'reason'); END IF;
 IF t.transaction_type IN ('Opening','Restock','Sale') THEN
 SELECT * INTO STRICT u FROM public.product_unit WHERE unit_id=(a->>'unit_id')::bigint AND variation_id=sp.variation_id AND status='Active';
 q:=(a->>'entered_quantity')::integer; IF q IS NULL OR q<1 OR q>1000000 THEN RAISE EXCEPTION 'Enter a whole quantity from 1 to 1000000.'; END IF;
 t.unit_id:=u.unit_id; t.entered_quantity:=q; t.units_per_package:=u.stock_units; t.quantity_change:=q*u.stock_units;
 IF t.transaction_type='Sale' THEN
 SELECT * INTO STRICT opt FROM public.store_price WHERE store_product_id=sp.store_product_id AND unit_id=u.unit_id AND status='Active' AND regular_price IS NOT NULL;
 IF NOT private.active_option(opt.store_price_id) THEN RAISE EXCEPTION 'This selling option is not active.'; END IF;
 SELECT price_history_id INTO STRICT history FROM public.price_history WHERE store_price_id=opt.store_price_id ORDER BY price_history_id DESC LIMIT 1;
 SELECT e.promotion_entry_id,e.promotion_price INTO promo,effective FROM public.promotion_entry e JOIN public.promotion p USING(promotion_id) WHERE e.store_price_id=opt.store_price_id AND e.status='Approved' AND p.status='Open' AND now()>=p.starts_at AND now()<p.ends_at AND e.promotion_price<opt.regular_price ORDER BY e.promotion_entry_id DESC LIMIT 1;
 expected:=coalesce(effective,opt.regular_price)*q;
 t.total_sale_amount:=CASE WHEN nullif(a->>'total_sale_amount','') IS NULL THEN private.money(expected::text) ELSE private.money(a->>'total_sale_amount') END;
 IF t.total_sale_amount<>expected AND t.reason IS NULL THEN RAISE EXCEPTION 'The charge differs from the listed price. Enter a reason.'; END IF;
 t.quantity_change:=-t.quantity_change; t.unit_purchase_cost:=sp.latest_unit_cost; t.price_history_id:=history; t.promotion_entry_id:=promo;
 ELSE
 IF t.transaction_type='Opening' AND EXISTS(SELECT 1 FROM public.stock_transaction WHERE store_product_id=sp.store_product_id) THEN RAISE EXCEPTION 'Opening stock must be the first movement.'; END IF;
 IF nullif(a->>'total_purchase_cost','') IS NOT NULL THEN t.total_purchase_cost:=private.money(a->>'total_purchase_cost',true); t.unit_purchase_cost:=round(t.total_purchase_cost/t.quantity_change,6); END IF;
 END IF;
 ELSIF t.transaction_type IN ('Loss','Spoilage','Damage') THEN
 q:=(a->>'quantity_change')::integer; IF q IS NULL OR q<1 THEN RAISE EXCEPTION 'Enter the stock units removed.'; END IF; t.quantity_change:=-q;
 ELSIF t.transaction_type='Correction' THEN
 t.quantity_change:=(a->>'quantity_change')::integer; t.unit_purchase_cost:=nullif(a->>'unit_purchase_cost','')::numeric;
 IF t.unit_purchase_cost IS NOT NULL AND (t.unit_purchase_cost<0 OR t.unit_purchase_cost>1000000000 OR t.unit_purchase_cost::text IN ('NaN','Infinity','-Infinity') OR t.unit_purchase_cost<>round(t.unit_purchase_cost,6)) THEN RAISE EXCEPTION 'Enter a valid unit cost with up to six decimals.'; END IF;
 IF t.quantity_change IS NULL OR (t.quantity_change=0 AND t.unit_purchase_cost IS NULL) THEN RAISE EXCEPTION 'Enter a signed stock change or corrected unit cost.'; END IF;
 t.correction_of_id:=nullif(a->>'correction_of_id','')::bigint;
 IF t.correction_of_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.stock_transaction WHERE stock_transaction_id=t.correction_of_id AND store_product_id=sp.store_product_id) THEN RAISE EXCEPTION 'The earlier movement must belong to this product.'; END IF;
 ELSIF t.transaction_type='Reversal' THEN
 SELECT * INTO STRICT old FROM public.stock_transaction WHERE stock_transaction_id=(a->>'correction_of_id')::bigint AND store_product_id=sp.store_product_id;
 IF old.transaction_type='Reversal' THEN RAISE EXCEPTION 'A reversal cannot reverse another reversal.'; END IF;
 t.correction_of_id:=old.stock_transaction_id; t.quantity_change:=-old.quantity_change;
 t.unit_id:=old.unit_id;t.entered_quantity:=old.entered_quantity;t.units_per_package:=old.units_per_package;
 t.unit_purchase_cost:=old.unit_purchase_cost;t.price_history_id:=old.price_history_id;t.promotion_entry_id:=old.promotion_entry_id;
 t.total_sale_amount:=-old.total_sale_amount;t.total_purchase_cost:=-old.total_purchase_cost;
 ELSE RAISE EXCEPTION 'Choose a valid stock transaction.';
 END IF;
 IF abs(t.quantity_change)>100000000 OR sp.stock_quantity::bigint+t.quantity_change NOT BETWEEN 0 AND 1000000000 THEN RAISE EXCEPTION 'The movement would cause an invalid stock balance.'; END IF;
 INSERT INTO public.stock_transaction(store_product_id,recorded_by,transaction_type,quantity_change,unit_id,entered_quantity,units_per_package,total_purchase_cost,total_sale_amount,unit_purchase_cost,price_history_id,promotion_entry_id,correction_of_id,reason,recorded_at)
 VALUES(t.store_product_id,t.recorded_by,t.transaction_type,t.quantity_change,t.unit_id,t.entered_quantity,t.units_per_package,t.total_purchase_cost,t.total_sale_amount,t.unit_purchase_cost,t.price_history_id,t.promotion_entry_id,t.correction_of_id,t.reason,t.recorded_at) RETURNING stock_transaction_id INTO t.stock_transaction_id;
 SELECT x.unit_purchase_cost INTO cost FROM public.stock_transaction x WHERE x.store_product_id=sp.store_product_id AND (x.transaction_type IN ('Opening','Restock') OR (x.transaction_type='Correction' AND x.unit_purchase_cost IS NOT NULL)) AND NOT EXISTS(SELECT 1 FROM public.stock_transaction rev WHERE rev.transaction_type='Reversal' AND rev.correction_of_id=x.stock_transaction_id) ORDER BY x.stock_transaction_id DESC LIMIT 1;
 UPDATE public.store_product SET stock_quantity=sp.stock_quantity+t.quantity_change,latest_unit_cost=cost WHERE store_product_id=sp.store_product_id;
 RETURN jsonb_build_object('id',t.stock_transaction_id,'message','Stock movement recorded.');
END $$;

CREATE EXTENSION IF NOT EXISTS unaccent WITH SCHEMA extensions;
CREATE FUNCTION private.clean(value text) RETURNS text LANGUAGE sql STABLE SET search_path = '' AS $$ SELECT trim(regexp_replace(lower(extensions.unaccent(coalesce(value,''))),'\s+',' ','g')) $$;
CREATE FUNCTION private.catalog_action(action text,a jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE uid uuid; id bigint; v bigint; u bigint; sp bigint; new_status text; req public.product_request; key text; q numeric; n integer;
BEGIN
 uid:=private.require_role(ARRAY['Administrator']);
 IF action='category' THEN
 INSERT INTO public.category(category_name,product_type) VALUES(private.required(a->>'category_name','category name'),a->>'product_type') RETURNING category_id INTO id;
 ELSIF action='brand' THEN
 INSERT INTO public.brand(brand_name,search_key) VALUES(private.required(a->>'brand_name','brand name'),private.clean(a->>'brand_name')) RETURNING brand_id INTO id;
 ELSIF action='product' THEN
 INSERT INTO public.product(category_id,brand_id,product_name,model_or_style) VALUES((a->>'category_id')::bigint,nullif(a->>'brand_id','')::bigint,private.required(a->>'product_name','product name'),nullif(trim(a->>'model_or_style'),'')) RETURNING product_id INTO id;
 ELSIF action='variation' THEN
 q:=nullif(a->>'net_quantity','')::numeric;
 IF a->>'net_unit' IN ('kg','L') THEN q:=q*1000; END IF;
 key:=private.clean(concat_ws('|',a->>'variation_name',a->>'size',a->>'color',a->>'flavor',a->>'capacity',q::text,CASE a->>'net_unit' WHEN 'kg' THEN 'g' WHEN 'L' THEN 'mL' ELSE a->>'net_unit' END,coalesce(a->>'condition','New'),a->>'stock_unit',a->>'other_details'));
 INSERT INTO public.product_variation(product_id,variation_name,size,color,flavor,capacity,net_quantity,net_unit,condition,stock_unit,other_details,variation_key,allow_price_reference)
 VALUES((a->>'product_id')::bigint,private.required(a->>'variation_name','variation name'),nullif(trim(a->>'size'),''),nullif(trim(a->>'color'),''),nullif(trim(a->>'flavor'),''),nullif(trim(a->>'capacity'),''),q,CASE a->>'net_unit' WHEN 'kg' THEN 'g' WHEN 'L' THEN 'mL' ELSE nullif(a->>'net_unit','') END,coalesce(a->>'condition','New'),private.required(a->>'stock_unit','stock unit'),nullif(trim(a->>'other_details'),''),key,coalesce((a->>'allow_price_reference')::boolean,false)) RETURNING variation_id INTO id;
 ELSIF action='unit' THEN
 n:=(a->>'stock_units')::integer; IF n<1 OR n>1000000 THEN RAISE EXCEPTION 'Enter 1 to 1000000 stock units per package.'; END IF;
 INSERT INTO public.product_unit(variation_id,unit_name,stock_units,gtin) VALUES((a->>'variation_id')::bigint,private.clean(private.required(a->>'unit_name','selling unit name')),n,nullif(trim(a->>'gtin'),'')) RETURNING unit_id INTO id;
 ELSIF action='catalog_status' THEN
 IF a->>'table' NOT IN ('category','brand','product','product_variation','product_unit') THEN RAISE EXCEPTION 'Choose a catalog record.'; END IF;
 new_status:=a->>'status'; IF new_status NOT IN ('Active','Archived') THEN RAISE EXCEPTION 'Choose Active or Archived.'; END IF;
 key:=CASE a->>'table' WHEN 'category' THEN 'category_id' WHEN 'brand' THEN 'brand_id' WHEN 'product' THEN 'product_id' WHEN 'product_variation' THEN 'variation_id' ELSE 'unit_id' END;
 EXECUTE format('UPDATE public.%I SET status=$1 WHERE %I=$2',a->>'table',key) USING new_status,(a->>'id')::bigint;
 ELSIF action='review_product' THEN
 SELECT * INTO STRICT req FROM public.product_request WHERE product_request_id=(a->>'product_request_id')::bigint FOR UPDATE;
 IF req.status<>'Pending Product Review' THEN RAISE EXCEPTION 'This request is already decided.'; END IF;
 new_status:=a->>'decision'; IF new_status NOT IN ('Approved','Rejected') THEN RAISE EXCEPTION 'Choose Approved or Rejected.'; END IF;
 IF new_status='Approved' THEN
 SELECT variation_id,unit_id INTO STRICT v,u FROM public.product_unit WHERE unit_id=(a->>'unit_id')::bigint AND status='Active';
 IF NOT EXISTS(SELECT 1 FROM public.product_variation pv JOIN public.product p USING(product_id) JOIN public.category c USING(category_id) LEFT JOIN public.brand b USING(brand_id) WHERE pv.variation_id=v AND pv.status='Active' AND p.status='Active' AND c.status='Active' AND (b.brand_id IS NULL OR b.status='Active')) THEN RAISE EXCEPTION 'Choose approved active product details.'; END IF;
 INSERT INTO public.store_product(sme_id,variation_id) VALUES(req.sme_id,v) ON CONFLICT(sme_id,variation_id) DO UPDATE SET status='Active' RETURNING store_product_id INTO sp;
 INSERT INTO public.store_price(store_product_id,unit_id) VALUES(sp,u) ON CONFLICT(store_product_id,unit_id) DO UPDATE SET status='Active';
 END IF;
 UPDATE public.product_request SET status=new_status,reviewed_by=uid,reviewed_at=now(),decision_reason=private.required(a->>'decision_reason','decision reason'),approved_variation_id=v,approved_unit_id=u WHERE product_request_id=req.product_request_id;
 ELSE RAISE EXCEPTION 'Unknown catalog action.';
 END IF;
 RETURN jsonb_build_object('id',id,'message','Catalog record saved.');
END $$;

CREATE FUNCTION private.promotion_action(action text,a jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE uid uuid; p public.promotion; e public.promotion_entry; opt public.store_price; hist bigint; id bigint; discount numeric; decision text; prior bigint;
BEGIN
 uid:=private.require_role(ARRAY['Administrator','Owner']); PERFORM pg_advisory_xact_lock(731901);
 IF action='promotion' THEN
 PERFORM private.require_role(ARRAY['Administrator']);
 INSERT INTO public.promotion(promotion_name,description,starts_at,ends_at,created_by) VALUES(private.required(a->>'promotion_name','event name'),nullif(trim(a->>'description'),''),(a->>'starts_at')::timestamptz,(a->>'ends_at')::timestamptz,uid) RETURNING promotion_id INTO id;
 ELSIF action='cancel_promotion' THEN
 PERFORM private.require_role(ARRAY['Administrator']); UPDATE public.promotion SET status='Cancelled' WHERE promotion_id=(a->>'promotion_id')::bigint;
 ELSIF action='promotion_entry' THEN
 opt:=private.own_option((a->>'store_price_id')::bigint);
 SELECT * INTO STRICT p FROM public.promotion WHERE promotion_id=(a->>'promotion_id')::bigint AND status='Open' AND ends_at>now();
 discount:=private.money(a->>'promotion_price');
 IF opt.regular_price IS NULL OR discount>=opt.regular_price THEN RAISE EXCEPTION 'The promotion price must be below the approved regular price.'; END IF;
 SELECT price_history_id INTO STRICT hist FROM public.price_history WHERE store_price_id=opt.store_price_id ORDER BY price_history_id DESC LIMIT 1;
 prior:=nullif(a->>'previous_entry_id','')::bigint;
 IF prior IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.promotion_entry WHERE promotion_entry_id=prior AND store_price_id=opt.store_price_id AND promotion_id=p.promotion_id AND status IN ('Rejected','Withdrawn')) THEN RAISE EXCEPTION 'Choose an earlier rejected or withdrawn entry for this event and listing.'; END IF;
 INSERT INTO public.promotion_entry(promotion_id,store_price_id,submitted_by,submitted_at,promotion_price,regular_history_id,previous_entry_id) VALUES(p.promotion_id,opt.store_price_id,uid,now(),discount,hist,prior) RETURNING promotion_entry_id INTO id;
 ELSIF action IN ('review_promotion','withdraw_promotion') THEN
 SELECT * INTO STRICT e FROM public.promotion_entry WHERE promotion_entry_id=(a->>'promotion_entry_id')::bigint FOR UPDATE;
 SELECT * INTO STRICT opt FROM public.store_price WHERE store_price_id=e.store_price_id FOR UPDATE;
 SELECT * INTO STRICT p FROM public.promotion WHERE promotion_id=e.promotion_id;
 IF action='withdraw_promotion' THEN
 PERFORM private.own_option(opt.store_price_id); IF e.status NOT IN ('Pending','Approved') THEN RAISE EXCEPTION 'This entry cannot be withdrawn.'; END IF;
 UPDATE public.promotion_entry SET status='Withdrawn',decision_reason=concat_ws(' | ',decision_reason,'Owner withdrew: '||private.required(a->>'decision_reason','withdrawal reason')) WHERE promotion_entry_id=e.promotion_entry_id;
 ELSE
 PERFORM private.require_role(ARRAY['Administrator']);
 IF e.status<>'Pending' THEN RAISE EXCEPTION 'This entry is already decided.'; END IF;
 decision:=a->>'decision'; IF decision NOT IN ('Approved','Rejected') THEN RAISE EXCEPTION 'Choose Approved or Rejected.'; END IF;
 IF decision='Approved' THEN
 IF NOT private.active_option(opt.store_price_id) OR p.status<>'Open' OR p.ends_at<=now() OR e.promotion_price>=opt.regular_price THEN RAISE EXCEPTION 'The event or price is no longer valid.'; END IF;
 SELECT price_history_id INTO hist FROM public.price_history WHERE store_price_id=opt.store_price_id ORDER BY price_history_id DESC LIMIT 1;
 IF hist<>e.regular_history_id THEN RAISE EXCEPTION 'The regular price changed. Ask the Owner to resubmit.'; END IF;
 IF EXISTS(SELECT 1 FROM public.promotion_entry x JOIN public.promotion xp USING(promotion_id) WHERE x.store_price_id=opt.store_price_id AND x.status='Approved' AND xp.status='Open' AND xp.starts_at<p.ends_at AND xp.ends_at>p.starts_at) THEN RAISE EXCEPTION 'Another approved promotion overlaps this event.'; END IF;
 END IF;
 UPDATE public.promotion_entry SET status=decision,reviewed_by=uid,decided_at=now(),decision_reason=private.required(a->>'decision_reason','decision reason') WHERE promotion_entry_id=e.promotion_entry_id;
 END IF;
 ELSE RAISE EXCEPTION 'Unknown promotion action.'; END IF;
 RETURN jsonb_build_object('id',id,'message','Promotion record saved.');
END $$;

CREATE FUNCTION private.mis_command(action text,a jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE uid uuid; role_name text; id bigint; sp public.store_product; opt public.store_price; u public.product_unit; r public.price_request; cr public.customer_report; status_value text; n integer; title text; amount numeric;
BEGIN
 uid:=private.require_role(ARRAY['Administrator','Owner','Customer']); role_name:=private.current_role();
 IF jsonb_typeof(a)<>'object' OR octet_length(a::text)>30000 THEN RAISE EXCEPTION 'Invalid request.'; END IF;
 IF action IN ('category','brand','product','variation','unit','catalog_status','review_product') THEN RETURN private.catalog_action(action,a);
 ELSIF action IN ('promotion','cancel_promotion','promotion_entry','review_promotion','withdraw_promotion') THEN RETURN private.promotion_action(action,a);
 ELSIF action='submit_price' THEN RETURN private.submit_price(a);
 ELSIF action='review_price' THEN RETURN private.review_price(a);
 ELSIF action='stock' THEN RETURN private.record_stock(a);
 ELSIF action='complete_registration' THEN
 -- Selecting Owner is an allowed public registration choice; Administrator is never self-assigned.
 IF a->>'role' NOT IN ('Owner','Customer') OR role_name='Administrator' THEN RAISE EXCEPTION 'Choose Owner or Customer.'; END IF;
 IF role_name='Owner' AND a->>'role'='Customer' THEN RAISE EXCEPTION 'An Owner account cannot be changed to Customer.'; END IF;
 UPDATE public.user_account SET role=a->>'role',full_name=left(private.required(a->>'full_name','full name'),120) WHERE user_id=uid;
 ELSIF action='profile' THEN UPDATE public.user_account SET full_name=left(private.required(a->>'full_name','full name'),120) WHERE user_id=uid;
 ELSIF action='store' THEN
 PERFORM private.require_role(ARRAY['Owner']);
 INSERT INTO public.sme(owner_id,store_name,business_type,address,registered_at) VALUES(uid,left(private.required(a->>'store_name','store name'),160),left(private.required(a->>'business_type','business type'),120),private.required(a->>'address','address'),now()) RETURNING sme_id INTO id;
 ELSIF action='store_status' THEN
 PERFORM private.require_role(ARRAY['Administrator']); status_value:=a->>'status'; IF status_value NOT IN ('Active','Inactive') THEN RAISE EXCEPTION 'Choose Active or Inactive.'; END IF;
 UPDATE public.sme SET status=status_value WHERE sme_id=(a->>'sme_id')::bigint;
 ELSIF action='account_status' THEN
 PERFORM private.require_role(ARRAY['Administrator']); status_value:=a->>'status'; IF status_value NOT IN ('Active','Inactive') THEN RAISE EXCEPTION 'Choose Active or Inactive.'; END IF;
 IF (a->>'user_id')::uuid=uid OR EXISTS(SELECT 1 FROM public.user_account WHERE user_id=(a->>'user_id')::uuid AND role='Administrator') THEN RAISE EXCEPTION 'Administrator accounts are managed through the database owner.'; END IF;
 UPDATE public.user_account SET status=status_value WHERE user_id=(a->>'user_id')::uuid;
 ELSIF action='list_unit' THEN
 PERFORM private.own_store((a->>'sme_id')::bigint);
 SELECT * INTO STRICT u FROM public.product_unit WHERE unit_id=(a->>'unit_id')::bigint AND status='Active';
 IF NOT EXISTS(SELECT 1 FROM public.product_variation v JOIN public.product p USING(product_id) JOIN public.category c USING(category_id) LEFT JOIN public.brand b USING(brand_id) WHERE v.variation_id=u.variation_id AND v.status='Active' AND p.status='Active' AND c.status='Active' AND (b.brand_id IS NULL OR b.status='Active')) THEN RAISE EXCEPTION 'Choose an active shared product.'; END IF;
 INSERT INTO public.store_product(sme_id,variation_id) VALUES((a->>'sme_id')::bigint,u.variation_id) ON CONFLICT(sme_id,variation_id) DO UPDATE SET status='Active' RETURNING store_product_id INTO id;
 INSERT INTO public.store_price(store_product_id,unit_id) VALUES(id,u.unit_id) ON CONFLICT(store_product_id,unit_id) DO UPDATE SET status='Active';
 ELSIF action='listing_status' THEN
 PERFORM private.require_role(ARRAY['Owner']); status_value:=a->>'status'; IF status_value NOT IN ('Active','Archived') THEN RAISE EXCEPTION 'Choose Active or Archived.'; END IF;
 SELECT * INTO STRICT opt FROM public.store_price WHERE store_price_id=(a->>'store_price_id')::bigint FOR UPDATE;
 SELECT * INTO STRICT sp FROM public.store_product WHERE store_product_id=opt.store_product_id;
 PERFORM private.own_store(sp.sme_id); UPDATE public.store_price SET status=status_value WHERE store_price_id=opt.store_price_id;
 ELSIF action='product_request' THEN
 PERFORM private.own_store((a->>'sme_id')::bigint);
 INSERT INTO public.product_request(sme_id,submitted_by,requested_details,submitted_at) VALUES((a->>'sme_id')::bigint,uid,private.required(a->>'requested_details','product details'),now()) RETURNING product_request_id INTO id;
 ELSIF action='price_explanation' OR action='withdraw_price' THEN
 SELECT * INTO STRICT r FROM public.price_request WHERE price_request_id=(a->>'price_request_id')::bigint FOR UPDATE;
 opt:=private.own_option(r.store_price_id);
 IF r.status<>'Pending Price Review' THEN RAISE EXCEPTION 'This request is no longer pending.'; END IF;
 IF action='price_explanation' THEN UPDATE public.price_request SET owner_reason=private.required(a->>'owner_reason','explanation') WHERE price_request_id=r.price_request_id;
 ELSE UPDATE public.price_request SET status='Withdrawn',decided_at=now(),decision_reason=private.required(a->>'decision_reason','withdrawal reason') WHERE price_request_id=r.price_request_id; END IF;
 ELSIF action='rule' THEN
 PERFORM private.require_role(ARRAY['Administrator']); PERFORM pg_advisory_xact_lock(731901);
 amount:=private.money(a->>'allowance_percent',true); n:=(a->>'minimum_stores')::integer;
 IF n NOT BETWEEN 1 AND 10000 OR (a->>'maximum_age_days')::integer NOT BETWEEN 1 AND 3650 THEN RAISE EXCEPTION 'Enter a valid reference count and maximum age.'; END IF;
 UPDATE public.price_rule SET status='Inactive' WHERE status='Active';
 INSERT INTO public.price_rule(allowance_percent,minimum_stores,maximum_age_days,effective_from,created_by) VALUES(amount,n,(a->>'maximum_age_days')::integer,now(),uid) RETURNING rule_id INTO id;
 ELSIF action='low_stock' THEN
 sp:=private.own_product((a->>'store_product_id')::bigint); n:=(a->>'low_stock_level')::integer;
 IF n NOT BETWEEN 0 AND 100000000 THEN RAISE EXCEPTION 'Enter a valid low-stock level.'; END IF;
 UPDATE public.store_product SET low_stock_level=n WHERE store_product_id=sp.store_product_id;
 ELSIF action='customer_report' THEN
 PERFORM private.require_role(ARRAY['Customer']);
 SELECT * INTO STRICT opt FROM public.store_price WHERE store_price_id=(a->>'store_price_id')::bigint;
 IF NOT private.active_option(opt.store_price_id) OR opt.regular_price IS NULL THEN RAISE EXCEPTION 'Choose an active listed product.'; END IF;
 INSERT INTO public.customer_report(customer_id,store_price_id,listed_price,charged_price,transaction_at,description,evidence_reference,submitted_at)
 VALUES(uid,opt.store_price_id,private.money(a->>'listed_price'),CASE WHEN nullif(a->>'charged_price','') IS NOT NULL THEN private.money(a->>'charged_price') END,nullif(a->>'transaction_at','')::timestamptz,private.required(a->>'description','report details'),nullif(trim(a->>'evidence_reference'),''),now()) RETURNING customer_report_id INTO id;
 ELSIF action='report_response' THEN
 SELECT * INTO STRICT cr FROM public.customer_report WHERE customer_report_id=(a->>'customer_report_id')::bigint FOR UPDATE;
 opt:=private.own_option(cr.store_price_id);
 IF cr.status='Closed' THEN RAISE EXCEPTION 'This report is already closed.'; END IF;
 UPDATE public.customer_report SET owner_response=private.required(a->>'owner_response','response'),responded_by=uid,responded_at=now() WHERE customer_report_id=cr.customer_report_id;
 ELSIF action='review_report' THEN
 PERFORM private.require_role(ARRAY['Administrator']);
 SELECT * INTO STRICT cr FROM public.customer_report WHERE customer_report_id=(a->>'customer_report_id')::bigint FOR UPDATE;
 IF cr.status='Closed' THEN RAISE EXCEPTION 'This report is already closed.'; END IF;
 status_value:=a->>'status'; IF status_value NOT IN ('Under Review','Closed') THEN RAISE EXCEPTION 'Choose Under Review or Closed.'; END IF;
 title:=nullif(a->>'outcome','');
 IF status_value='Closed' AND (title IS NULL OR title NOT IN ('Confirmed Discrepancy','Package Mismatch','Insufficient Evidence','No Discrepancy Established')) THEN RAISE EXCEPTION 'Choose a closure outcome.'; END IF;
 UPDATE public.customer_report SET status=status_value,reviewed_by=uid,outcome=CASE WHEN status_value='Closed' THEN title END,outcome_details=private.required(a->>'outcome_details','review findings'),closed_at=CASE WHEN status_value='Closed' THEN now() END WHERE customer_report_id=cr.customer_report_id;
 ELSE RAISE EXCEPTION 'Unknown action.';
 END IF;
 RETURN jsonb_build_object('id',id,'message','Saved successfully.');
END $$;
CREATE FUNCTION public.mis_command(action text,a jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT private.mis_command(action,a) $$;
REVOKE ALL ON FUNCTION public.mis_command(text,jsonb) FROM public,anon;
GRANT EXECUTE ON FUNCTION public.mis_command(text,jsonb) TO authenticated;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA private FROM public,anon,authenticated;
GRANT EXECUTE ON FUNCTION private.current_role(),private.can_store(bigint),private.can_product(bigint),private.can_price(bigint),private.mis_command(text,jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION private.public_listings(text) TO anon,authenticated;
-- Every foreign key has a leading-column index for predictable reviews and deletes.
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT t.relname table_name,a.attname column_name FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace ns ON ns.oid=t.relnamespace JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=c.conkey[1] WHERE c.contype='f' AND ns.nspname='public' LOOP
 EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I(%I)',r.table_name||'_'||r.column_name||'_fk',r.table_name,r.column_name);
 END LOOP;
END $$;
